const getRentalLegKm = `-- name: GetRentalLegKm :one
SELECT COALESCE(SUM(rv.in_km - rv.out_km) FILTER (WHERE rv.in_km IS NOT NULL AND rv.out_km IS NOT NULL), 0)::bigint AS driven_km,
    COALESCE(MAX(rv.out_km) FILTER (WHERE rv.in_km IS NULL), 0)::int AS open_out_km,
    COALESCE(MAX(rv.out_fuel::int) FILTER (WHERE rv.in_km IS NULL), -1)::int AS open_out_fuel
FROM rental_vehicles rv
WHERE rv.organization_id = $1
  AND rv.rental_id = $2
`

type GetRentalLegKmParams struct {
	OrganizationID int64 `json:"organization_id"`
	RentalID       int64 `json:"rental_id"`
}

type GetRentalLegKmRow struct {
	DrivenKm    int64 `json:"driven_km"`
	OpenOutKm   int32 `json:"open_out_km"`
	OpenOutFuel int32 `json:"open_out_fuel"`
}

// Km out / in of the rental's legs (driven km of the whole rental).
func (q *Queries) GetRentalLegKm(ctx context.Context, arg GetRentalLegKmParams) (GetRentalLegKmRow, error) {
	row := q.db.QueryRow(ctx, getRentalLegKm, arg.OrganizationID, arg.RentalID)
	var i GetRentalLegKmRow
	err := row.Scan(&i.DrivenKm, &i.OpenOutKm, &i.OpenOutFuel)
	return i, err
}

